[meta]
name = Vesperholm
ambient = 0.52 0.57 0.72
fog = 0.34 0.39 0.53
fog_range = 14 84
model_range = 46
indoor_range = 26
sky = moonlit
torch = 6 0.62 0.68 0.82
start = 21 54 -90
default = ,
entity_floor = auto
edge_top = 9
edge_tex = moonstone

// Vesperholm, the Moonbound City, behind the Vesper Gate in Harrowmere's north wall at the head of the
// cathedral steps, which stands open to anyone who climbs them: the seat of the king's sister, Duchess
// Ilvane, who wed the moon on the fourth sigil so the night would never end and nothing in her city
// would die. The moon stopped over it, vast, full and pale, and has hung in the north
// over her cathedral ever since; everything under it is drowned in its light, and every soul in the
// city has thinned to a moonlit shade of itself. You come through the gate into the Gate Court and its
// shrine; north of it Lantern Square and its moon pool, the Landing on the gorge's edge, with the
// castle's raised drawbridge across the gorge, and Lamplighters' Row east. The way over is the Glass
// Bridge at the west street's head, into the castle's postern; its bailey, the west chapel and the
// Duchess's pale garden; and at its heart the Cathedral of the Long Night, the nave and, behind its
// great door, the choir where the Duchess waits. The drawbridge's lever, in the bailey, is the short
// way back to the shrine.

[legend]
# = wall tex=moonstone top=9 cap=silver_slate
% = wall tex=moonstone top=14 cap=silver_slate
h = wall tex=moonstone top=5.5 cap=silver_slate
, = floor tex=moon_paving h=0 side=moonstone
// The moon pool in the square: shallow, it only casts you back out.
~ = water tex=water h=-0.6 side=moonstone
// The gorge between the lower town and the castle: a sheer drop, far too deep to live through.
_ = floor tex=moon_paving h=-18 side=moonstone chasm
// The Glass Bridge: a deck of frosted moon-glass over the gorge.
g = floor tex=moon_glass h=0 side=moonstone
// The passages through the castle's walls.
p = floor tex=moon_paving h=0 ceil=4.5 ceil_tex=moonstone side=moonstone
// The west chapel, the nave and the choir.
a = floor tex=moon_paving h=0 ceil=4.2 ceil_tex=silver_slate side=moonstone dark=0.3
n = floor tex=moon_paving h=0 ceil=12 ceil_tex=silver_slate side=moonstone dark=0.2
c = floor tex=moon_glass h=0 ceil=13 ceil_tex=silver_slate side=moonstone dark=0.15

