[entities]
// The Vesper Gate home to Harrowmere, in the Gate Court's south wall, and the court's shrine.
A = exit map=harrowmere at=22,2,90 label=Return_to_Harrowmere model=vesper_gate yaw=-90
B = save_statue
Q = hint text="The moon here never sets, and it keeps all it shines on.|Nothing in this city has died. Nothing in it lives."
R = hint text="Across the gorge the castle's drawbridge stands raised.|Its lever must lie on the far side."
// Duchess Ilvane in the choir of her cathedral, behind its great door.
D = moon_duchess
E = door boss=duchess_dead on=n
// The castle's drawbridge over the gorge, let down by the lever in the bailey: the short way back to
// the shrine.
F = bridge lever=vesper_bridge hinge=n deck=0 on=_
G = lever id=vesper_bridge
// A false wall behind the square's east houses, into a hidden court.
W = secret_wall on=,
// The moonlit dead: sentinels of silvered plate, lantern wraiths, moonhounds and veiled knights.
S = pale_sentinel
L = lantern_wraith
M = moonhound
V = veiled_knight
// Finds: remedies, and gold the dead no longer spend.
C = chest item=red_tonic count=2 gold=90
I = chest item=blue_moss count=2 gold=120
J = chest item=grave_lily gold=160 model=coffer
K = chest item=menders_kit gold=140 model=banded
N = chest item=clotting_salve count=2 gold=110
O = chest item=bitter_root count=2 gold=100 model=coffer
